    const respText = await r.text();
    if (!r.ok) {
      console.error(`[${type}] FAILED: HTTP ${r.status}`, respText);
      throw new Error(`Stopped at ${type}; later drafts were NOT created.`);
    }
    console.log(`%c[${type}] Created.`, 'color:#22c55e', respText);
